package com.plciocheck.melsecmc.frame

import com.plciocheck.melsecmc.FrameException
import com.plciocheck.melsecmc.McProtocolException
import com.plciocheck.melsecmc.device.DeviceCode
import com.plciocheck.melsecmc.device.DeviceRef
import com.plciocheck.melsecmc.device.ModuleBufferAddress
import kotlin.test.*

/** Literal wire oracles transcribed from SH-080956ENG-N Appendix 1, not generated by the codec. */
internal object ModuleBufferContractCases {
    private fun hex(s: String) = s.split(' ').filter { it.isNotBlank() }.map { it.toInt(16).toByte() }.toByteArray()
    private val q = ModuleBufferProfile.Q
    private val r = ModuleBufferProfile.IQ_R
    private val three = FrameType.FRAME_3E
    private val four = FrameType.FRAME_4E
    private val binary = DataMode.BINARY
    private val ascii = DataMode.ASCII

    fun addressIdentity() {
        for (m in listOf(0, 1, 9, 10, 0x123, 0xFFF)) {
            for (n in listOf(0L, 1L, 100L, 999_999L, 0xFFFF_FFFFL)) {
                for (b in listOf(null, 0, 3, 15)) {
                    val address = ModuleBufferAddress(m, n, b)
                    assertEquals(address, ModuleBufferAddress.parseOrNull(address.toString()))
                    assertEquals(ModuleBufferAddress(m, n), address.wordAddress)
                }
            }
        }
        assertEquals(ModuleBufferAddress(10, 100, 15), ModuleBufferAddress.parseOrNull(" ua₩g00100.f "))
        assertNotEquals(ModuleBufferAddress(1, 100), ModuleBufferAddress(2, 100))
        assertNotEquals(ModuleBufferAddress(1, 100), ModuleBufferAddress(1, 100, 0))
        for (raw in listOf("G100", "U1000\\G0", "U1\\G-1", "U1\\G+1", "U1\\G1Z0", "U1\\G1.10",
            "U1\\G4294967296", "U1\\G1.0Z0", "@U1\\G1", "K4U1\\G1", "U1\\G1junk")) {
            assertNull(ModuleBufferAddress.parseOrNull(raw), raw)
        }
    }

    fun literalFrames() {
        val address = ModuleBufferAddress(1, 100)
        assertContentEquals(hex("50 00 00 FF FF 03 00 13 00 10 00 01 04 80 00 00 00 64 00 00 AB 00 00 01 00 F8 01 00"),
            ModuleBufferCodec(q, three, binary).encodeRead(address, 1).bytes)
        assertContentEquals(hex("50 00 00 FF FF 03 00 15 00 10 00 01 04 82 00 00 00 64 00 00 00 AB 00 00 00 01 00 F8 01 00"),
            ModuleBufferCodec(r, three, binary).encodeRead(address, 1).bytes)
        assertEquals("500000FF03FF00002400100401008000U001000G*0001000000001",
            ModuleBufferCodec(q, three, ascii).encodeRead(address, 1).bytes.toString(Charsets.US_ASCII))
        assertEquals("500000FF03FF00002A00100401008200U0010000G***0000010000000001",
            ModuleBufferCodec(r, three, ascii).encodeRead(address, 1).bytes.toString(Charsets.US_ASCII))
        val c = ModuleBufferCodec(q, four, binary)
        assertContentEquals(hex("54 00 00 00 00 00 00 FF FF 03 00 13 00 10 00 01 04 80 00 00 00 64 00 00 AB 00 00 01 00 F8 01 00"),c.encodeRead(address,1).bytes)
        assertEquals(1,c.encodeRead(address,1).serial)
        val a = ModuleBufferCodec(q, four, ascii)
        assertEquals("54000000000000FF03FF00002400100401008000U001000G*0001000000001",a.encodeRead(address,1).bytes.toString(Charsets.US_ASCII))
        assertEquals(1,a.encodeRead(address,1).serial)
        assertContentEquals(ModuleBufferCodec(q,three,ascii).encodeRead(address,1).bytes,
            ModuleBufferCodec(ModuleBufferProfile.FX5,three,ascii).encodeRead(address,1).bytes)
    }

    fun exactReplies() {
        for (profile in listOf(q,r)) {
            val c=ModuleBufferCodec(profile,three,binary);val req=c.encodeRead(ModuleBufferAddress(1,100),2)
            assertContentEquals(intArrayOf(0,0xFFFF),c.decodeRead(req,hex("D0 00 00 FF FF 03 00 06 00 00 00 00 00 FF FF")))
            val a=ModuleBufferCodec(profile,three,ascii);val ar=a.encodeRead(ModuleBufferAddress(1,100),2)
            assertContentEquals(intArrayOf(0,0xFFFF),a.decodeRead(ar,"D00000FF03FF00000C00000000FFFF".toByteArray()))
            val b4=ModuleBufferCodec(profile,four,binary); b4.encodeRead(ModuleBufferAddress(2,0),1)
            val r4=b4.encodeRead(ModuleBufferAddress(1,100),1)
            assertContentEquals(intArrayOf(0x1234),b4.decodeRead(r4,hex("D4 00 01 00 00 00 00 FF FF 03 00 04 00 00 00 34 12")))
            val a4=ModuleBufferCodec(profile,four,ascii);a4.encodeRead(ModuleBufferAddress(2,0),1)
            val ra4=a4.encodeRead(ModuleBufferAddress(1,100),1)
            assertContentEquals(intArrayOf(0x1234),a4.decodeRead(ra4,"D4000001000000FF03FF00000800001234".toByteArray()))
        }
    }

    fun malformedReplies() {
        val c=ModuleBufferCodec(q,three,binary);val req=c.encodeRead(ModuleBufferAddress(1,100),1)
        val valid=hex("D0 00 00 FF FF 03 00 04 00 00 00 34 12")
        for (n in 0 until valid.size) assertFailsWith<FrameException> { c.decodeRead(req,valid.copyOf(n)) }
        assertFailsWith<FrameException> { c.decodeRead(req,valid+0) }
        for (offset in listOf(0,1,2,3,4,5,6,7,8)) {
            val bad=valid.copyOf();bad[offset]=(bad[offset].toInt() xor 1).toByte()
            assertFailsWith<FrameException>("offset=$offset") { c.decodeRead(req,bad) }
        }
        assertFailsWith<FrameException> { c.decodeRead(req,hex("D0 00 00 FF FF 03 00 02 00 00 00")) }
        val err=assertFailsWith<McProtocolException> { c.decodeRead(req,hex("D0 00 00 FF FF 03 00 02 00 51 C0")) }
        assertTrue(err.message!!.isNotBlank())
        val a=ModuleBufferCodec(q,three,ascii); val ar=a.encodeRead(ModuleBufferAddress(1,100),1)
        val av="D00000FF03FF00000800001234"
        for (n in 0 until av.length) assertFailsWith<FrameException> { a.decodeRead(ar,av.take(n).toByteArray()) }
        for (bad in listOf(av+"0",av.replace("1234","+123"),av.replace("1234","Z234"),
            av.replace("1234","é234"),av.replace("0008","000C"),av.replace("03FF","03FE"))) {
            assertFailsWith<FrameException> { a.decodeRead(ar,bad.toByteArray()) }
        }
        assertFailsWith<McProtocolException> { a.decodeRead(ar,"D00000FF03FF000004C051".toByteArray()) }
        val c4=ModuleBufferCodec(q,four,binary);val rq=c4.encodeRead(ModuleBufferAddress(1,0),1)
        assertFailsWith<FrameException> { c4.decodeRead(rq,hex("D4 00 01 00 00 00 00 FF FF 03 00 04 00 00 00 00 00")) }
        assertFailsWith<FrameException> { c4.decodeRead(rq,hex("D4 00 00 00 01 00 00 FF FF 03 00 04 00 00 00 00 00")) }
        assertFailsWith<FrameException> { ModuleBufferCodec(q,three,binary).decodeRead(req,valid) }
        val copy=req.bytes;copy.fill(0);assertEquals(0x50,req.bytes[0].toInt())
    }

    fun fieldBounds() {
        for ((mode,limit) in listOf(binary to 0xFF_FFFFL,ascii to 999_999L)) {
            val c=ModuleBufferCodec(q,three,mode)
            c.encodeRead(ModuleBufferAddress(0xFFF,limit),1)
            assertFailsWith<FrameException> { c.encodeRead(ModuleBufferAddress(1,limit),2) }
        }
        for (count in listOf(0,961,Int.MAX_VALUE)) assertFailsWith<FrameException> {
            ModuleBufferCodec(q,three,binary).encodeRead(ModuleBufferAddress(1,0),count)
        }
        assertFailsWith<FrameException> { ModuleBufferCodec(q,three,binary).encodeRead(ModuleBufferAddress(1,0,0),2) }
        for (frame in listOf(three,four)) for (mode in listOf(binary,ascii)) {
            if (frame==three && mode==ascii) continue
            assertFailsWith<FrameException> { ModuleBufferCodec(ModuleBufferProfile.FX5,frame,mode).encodeRead(ModuleBufferAddress(1,0),1) }
        }
        assertFailsWith<IllegalArgumentException> { ModuleBufferAddress(0x1000,0) }
        assertFailsWith<IllegalArgumentException> { ModuleBufferAddress(0,-1) }
        assertFailsWith<IllegalArgumentException> { ModuleBufferCodec(q,three,binary,monitoringTimer=0) }
    }

    fun ordinaryGAndSerials() {
        for (frame in listOf(three,four)) for (mode in listOf(binary,ascii)) {
            val e=McFrameEncoder(frameType=frame,dataMode=mode)
            val ref=DeviceRef(DeviceCode.G,100)
            assertFailsWith<FrameException> { e.encodeBatchReadWord(ref,1) }
            assertFailsWith<FrameException> { e.encodeBatchReadBit(ref,1) }
            assertFailsWith<FrameException> { e.encodeBatchWriteWord(ref,intArrayOf(1)) }
            assertFailsWith<IllegalArgumentException> { e.encodeBatchWriteBit(ref,intArrayOf(1)) }
            assertTrue(e.encodeBatchReadWord(DeviceRef(DeviceCode.D,100),1).isNotEmpty())
        }
        val e=McFrameEncoder(frameType=four,dataMode=binary)
        val c=e.moduleBufferCodec(q)
        e.encodeBatchReadWord(DeviceRef(DeviceCode.D,0),1)
        val previous=e.lastSerialNo
        val packet=c.encodeRead(ModuleBufferAddress(1,0),1)
        assertEquals((previous+1) and 65535,packet.serial)
        e.encodeBatchReadWord(DeviceRef(DeviceCode.D,0),1)
        assertEquals((packet.serial+1) and 65535,e.lastSerialNo)
    }
}
